INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (1, 'Tikal', 'Tikal es un destino turístico muy popular y concurrido, esto ya dice que es una de las mejores ruinas mayas de Guatemala. Es muy visitado por personas de todo el mundo. De hecho, muchos vienen al país exclusivamente a visitar Tikal. Fue una ciudad importante para la civilización maya ya que su poderío socio-político era decisivo para el desarrollo económico de las poblaciones de la región. Su templo IV es el más alto: mide 70 metros de altura. Y encuentras una gran cantidad de estelas, tumbas y altares.<> El Parque Nacional Tikal está situado en el corazón de la selva tropical de Petén, en el norte de Guatemala. A unos 65 kilómetros al noreste de la ciudad de Flores y el aeropuerto internacional de Mundo Maya, Tikal es fácilmente accesible por carretera y aire, lo que lo convierte en un destino imprescindible para los amantes de la arqueología y la naturaleza.', 'Q200.00 a Q600', '8:00 a 18:00', './img/turismo/inicio1.jpg', 'lugar01');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (2, 'Iximché', 'Situado en las tierras altas de Guatemala, el sitio arqueológico de Iximché se encuentra a aproximadamente 90 kilómetros al oeste de la Ciudad de Guatemala, cerca de la moderna ciudad de Tecpán, Chimaltenango. Este impresionante sitio es de fácil acceso por carretera y es una excelente opción para una excursión de un día desde la capital.<> La ciudad de Iximché tiene 6 plazas y el área del Gran Palacio. En este sitio sucedió una de las más grandes alianzas entre los españoles y los kaqchikeles. Este vínculo servía para unificar fuerzas en contra de la etnia Quiché.', 'Q50 a Q100', '8:00 a 16:00', './img/turismo/iximche.jpg', 'lugar02');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (3, 'Zaculeo', 'Las ruinas de Zaculeu se encuentran en el departamento de Huehuetenango, en el altiplano occidental de Guatemala, a unos 5 kilómetros de la ciudad de Huehuetenango. Este sitio arqueológico es fácilmente accesible por carretera desde la ciudad, lo que lo convierte en una excelente opción para los viajeros que desean explorar la rica historia de la región.<> Zaculeu, cuyo nombre significa "Tierra Blanca" en el idioma Mam, fue la capital del reino Mam. La ciudad alcanzó su apogeo durante el período posclásico (900-1525 d.C.) y es conocida por su papel en la resistencia contra la conquista española liderada por Gonzalo de Alvarado en 1525. El sitio sirvió como una fortaleza defensiva y refugio para los Mam durante el asedio, lo que subraya su importancia estratégica y cultural.', 'Q5 a Q50', '8:00 a 16:00', './img/turismo/zaculeu.jpg', 'lugar03');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (4, 'Takalik Abaj', 'Takalik Abaj se encuentra en el departamento de Retalhuleu, en la costa sur de Guatemala. Situado aproximadamente a 190 kilómetros al suroeste de la Ciudad de Guatemala, este sitio arqueológico es accesible por carretera, lo que lo convierte en un destino ideal para una excursión de un día desde la ciudad capital o desde los destinos turísticos costeros.<> Takalik Abaj, que significa "Piedra Parada" en el idioma K\'iche\', es un sitio arqueológico excepcional que floreció durante el período preclásico (800 a.C. - 300 d.C.) y continuó siendo ocupado hasta el período clásico. Este sitio es notable por su mezcla de influencias olmecas y mayas, lo que lo convierte en un punto crucial para comprender la transición y la interacción entre estas dos grandes culturas mesoamericanas.', 'Q5 a Q50', '7:00 a 17:00', './img/turismo/takalik.jpg', 'lugar04');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (5, 'Mixco Viejo', 'Mixco Viejo se encuentra en el departamento de Chimaltenango, en el altiplano central de Guatemala, a unos 50 kilómetros al noroeste de la Ciudad de Guatemala. Este sitio arqueológico está ubicado en una meseta rodeada de profundos barrancos, lo que lo convierte en una fortaleza natural y un destino fascinante para los amantes de la historia y la arqueología.<> Mixco Viejo, conocido también como Jilotepeque Viejo, fue la capital del reino Poqomam durante el período posclásico (1200-1525 d.C.). La ciudad jugó un papel importante en la resistencia contra la conquista española liderada por Pedro de Alvarado en 1525. A pesar de su eventual caída, Mixco Viejo sigue siendo un símbolo de la resistencia y la rica herencia cultural de los Poqomam.', 'Q50 a Q100', '8:00 a 16:00', './img/turismo/mixco.jpeg', 'lugar05');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (6, 'Quiriguá', 'Quiriguá fue una pequeña ciudad en la que divergían rutas comerciales gracias a su cercanía al río Motagua. Su importancia reside en las estelas que posee. Fueron erigidas cada cinco años y narran en jeroglíficos los eventos socio-políticos de ciudad como por ejemplo, los cambios de mando de sus gobernantes. Además, aquí en Quiriguá verás la estela maya más alta del mundo.<> El Parque Arqueológico Quiriguá se encuentra en el departamento de Izabal, en el oriente de Guatemala. Ubicado a unos 205 kilómetros de la Ciudad de Guatemala y a 75 kilómetros de la ciudad portuaria de Puerto Barrios, este sitio es accesible por carretera, lo que lo convierte en un destino ideal para los viajeros que desean explorar la historia maya en un entorno exuberante.', 'Q80 a Q350', '8:00 a 17:00', './img/turismo/quirigua.png', 'lugar06');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (7, 'El Mirador', 'El Mirador se encuentra en el departamento de Petén, en el norte de Guatemala, en medio de la densa selva tropical. Este sitio arqueológico es uno de los más grandes y antiguos de la civilización maya, y se encuentra a unos 55 kilómetros al norte de la ciudad de Flores. Debido a su ubicación remota, el acceso a El Mirador es una aventura en sí misma, generalmente realizado a pie o en helicóptero desde Flores o Carmelita.<> Su importancia para la civilización maya fue su función de captación de agua y manejo de sistema de drenajes para el área. A 20 km de El Mirador se encuentra la segunda ciudad maya más grande: El Tintal. Estas antiguas ciudades mayas tuvieron su apogeo económico, social y político de la mano con Tikal. Su mayor atractivo es la Pirámide de La Danta. Es la pirámide maya más alta con sus 72 metros de altura.', 'Q450 a Q700', 'Depende del tour', './img/turismo/mirador.jpg', 'lugar07');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (8, 'Uaxactún', 'Uaxactún es la ruina maya vecina de Tikal. Se encuentra a 23 km de distancia hacia el norte. La importancia de Uaxactún era su potencia política, según investigaciones, más antigua que Tikal. Estas dos ciudades mayas mantuvieron conflicto territorial durante el apogeo de Tikal, hasta que Uaxactún terminó perdiendo la independencia.', 'Q50 a Q150', '6:00 a 18:00', './img/turismo/uaxactun.jpg', 'lugar08');
